using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Reflection.Emit;using System.Reflection.Metadata;using System.Reflection.Metadata.Ecma335;using System.Reflection.PortableExecutable;using System.Security.Cryptography;using System.Text.Json;
class Program {
static Dictionary<short,OpCode> codes=typeof(OpCodes).GetFields().Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)).ToDictionary(o=>o.Value);
static string TypeName(MetadataReader r,EntityHandle h){if(h.Kind==HandleKind.TypeReference){var t=r.GetTypeReference((TypeReferenceHandle)h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}if(h.Kind==HandleKind.TypeDefinition){var t=r.GetTypeDefinition((TypeDefinitionHandle)h);return r.GetString(t.Namespace)+"."+r.GetString(t.Name);}return h.Kind.ToString();}
static string Field(MetadataReader r,EntityHandle h){if(h.Kind==HandleKind.FieldDefinition){var f=r.GetFieldDefinition((FieldDefinitionHandle)h);return TypeName(r,f.GetDeclaringType())+"::"+r.GetString(f.Name);}if(h.Kind==HandleKind.MemberReference){var m=r.GetMemberReference((MemberReferenceHandle)h);if(m.GetKind()!=MemberReferenceKind.Field)return "";return TypeName(r,m.Parent)+"::"+r.GetString(m.Name);}return "";}
static bool Target(string s)=>s==".RebirthGameBridgeInput::Shift"||s==".RebirthGameBridgeInput::LockCursor";
static void Main(string[] args){var records=new List<object>();foreach(var path in Directory.EnumerateFiles(args[0],"*.dll",SearchOption.AllDirectories).OrderBy(x=>x)){var rel=Path.GetRelativePath(args[0],path);if(rel.Split(Path.DirectorySeparatorChar).Any(x=>x=="Tools"||x=="obj"||x=="bin"||x==".git")){records.Add(new{path,status="excluded-tool-or-build-artifact"});continue;}try{byte[] data=File.ReadAllBytes(path);string hash=Convert.ToHexString(SHA256.HashData(data));using var pe=new PEReader(new MemoryStream(data));if(!pe.HasMetadata){records.Add(new{path,hash,status="native-no-managed-metadata"});continue;}var r=pe.GetMetadataReader();var refs=new List<string>();foreach(var h in r.MemberReferences){var f=Field(r,h);if(Target(f))refs.Add(f);}var uses=new List<object>();int methods=0;foreach(var h in r.MethodDefinitions){var m=r.GetMethodDefinition(h);if(m.RelativeVirtualAddress==0)continue;methods++;var il=pe.GetMethodBody(m.RelativeVirtualAddress).GetILBytes();for(int i=0;i<il.Length;){int offset=i;short value=il[i++];if(value==0xfe)value=(short)(0xfe00|il[i++]);var op=codes[value];int len=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(il,i),_=>4};if(op.OperandType==OperandType.InlineField||op.OperandType==OperandType.InlineTok){var token=BitConverter.ToInt32(il,i);var f=Field(r,MetadataTokens.EntityHandle(token));if(Target(f))uses.Add(new{method=TypeName(r,m.GetDeclaringType())+"::"+r.GetString(m.Name),offset,opcode=op.Name,field=f,token});}i+=len;}}records.Add(new{path,hash,status="managed-scanned",assembly=r.IsAssembly?r.GetString(r.GetAssemblyDefinition().Name):"module",methods,metadataFieldReferences=refs,actualILReferences=uses});}catch(Exception e){records.Add(new{path,status="ERROR",error=e.ToString()});}}File.WriteAllText(args[1],JsonSerializer.Serialize(records,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("Manifest entries "+records.Count+"; inspect statuses/references in JSON; no target assemblies loaded.");}}
